INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "蹇义", "aliases": ["蹇義"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，蹇义出任吏部尚书。", "biography": null, "status": "draft", "id": "9ba158c7-e385-515d-a04d-b17a7bb11a0a"}, {"name": "黄淮", "aliases": ["黃淮"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）八月，黄淮以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "e32b0e82-1f00-53e4-bd5e-1b46eecf09ef"}, {"name": "杨士奇", "aliases": ["楊士奇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨士奇以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "cf93d13f-f48a-5fc6-8687-47933c0ca559"}, {"name": "杨溥（明代内阁大学士）", "aliases": ["楊溥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪熙元年（1425年）闰七月，杨溥以太常卿兼翰林学士身份共同处理内阁事务。", "biography": null, "status": "draft", "id": "1f1bfa42-5ca4-5450-84a8-f7927b05b3f7"}, {"name": "徐氏", "aliases": ["仁孝皇后", "仁孝文皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "徐氏安葬于长陵。", "biography": null, "status": "draft", "id": "c6b4fefb-6944-582a-a23c-c1463d3b3963"}, {"name": "阿鲁台", "aliases": ["和宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "阿鲁台受封和宁王。", "biography": null, "status": "draft", "id": "fd6d854f-724b-5621-91d3-593e412f448b"}, {"name": "顾成", "aliases": ["镇远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "顾成以镇远侯身份出兵。", "biography": null, "status": "draft", "id": "29ed6219-ab77-55f7-b128-4f4bb33ff1d0"}, {"name": "马哈木", "aliases": ["顺宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "马哈木所部渡过饮马河。", "biography": null, "status": "draft", "id": "2bbcd72b-9658-58e2-a44c-880d99f09ace"}, {"name": "陈懋", "aliases": ["宁阳侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈懋以宁阳侯身份巡边阅兵。", "biography": null, "status": "draft", "id": "e5696099-627f-57a5-b989-87e71d1b2e68"}, {"name": "张辅", "aliases": ["张文弼"], "era": "明", "birth_year": null, "death_year": null, "description": "张辅率军在爱子江交战。", "biography": null, "status": "draft", "id": "ef0d049d-1c37-5697-84d4-4274dfac2d2d"}, {"name": "沐晟", "aliases": ["沐景茂"], "era": "明", "birth_year": null, "death_year": null, "description": "沐晟率军在爱子江交战。", "biography": null, "status": "draft", "id": "525263d4-8c61-52a8-a6e9-265b6ac50d2a"}, {"name": "本雅失里", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "本雅失里被马哈木一方攻杀。", "biography": null, "status": "draft", "id": "a9f3a7f7-aca0-59ea-9d42-a1263cecd29b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "正月初一发生日食，朝廷取消朝贺与宴会", "description": "永乐十一年正月初一发生日食，朝廷随即下诏取消朝贺和宴会。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年正月辛巳朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64bcb900-acd0-57c8-b942-abd03f80d78d"}, {"title": "明廷要求朝觐官员如实上报灾情", "description": "永乐十一年正月壬午，明廷告谕通政使和礼科给事中，朝觐官员若隐瞒辖区灾情，待别人上报后发现，要追究该官员的责任。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年正月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3676ca8b-a664-5cf7-87a0-1fe198725ed5"}, {"title": "明成祖在南郊祭祀天地", "description": "永乐十一年正月辛卯，明成祖朱棣在南郊举行祭祀天地的大典。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年正月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e87bae1f-a3e7-5c93-8a73-cb71fa3f0a9e"}, {"title": "李彬镇守甘肃，宋琥被召回", "description": "永乐十一年正月辛丑，明廷派丰城侯李彬镇守甘肃，并召回宋琥。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年正月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e578e6a8-3019-539c-825d-d792fb3d0b6c"}, {"title": "明廷设立贵州布政司", "description": "永乐十一年二月辛亥，明廷首次设立贵州布政司，作为当地的地方行政机构。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a9458bbc-9d0a-5246-b949-8158f4454688"}, {"title": "明廷命北京民户分养种马", "description": "永乐十一年二月癸亥，朝廷规定由北京民户分担饲养用于繁殖的马匹，并将做法定为法令。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "371790ba-b27b-5d27-9b25-2d4ab7f9b133"}, {"title": "明成祖巡幸北京，皇太孙同行", "description": "永乐十一年二月甲子，明成祖朱棣决定巡幸北京，皇太孙朱瞻基随行。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b08c81e5-252e-5825-a4a0-8974adcb6aa5"}, {"title": "蹇义等人辅佐皇太子朱高炽监国", "description": "永乐十一年二月，明成祖巡幸北京期间，皇太子朱高炽监理国政。尚书蹇义、学士黄淮、谕德杨士奇和洗马杨溥辅佐他。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "79aa0e57-ab49-5d3e-975f-4239213bbe20"}, {"title": "明成祖离开京师，命沿途慰问老人", "description": "永乐十一年二月乙丑，明成祖自京师启程，命给事中和御史慰问沿途高龄老人，并赏赐酒、肉和帛。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "24d913ae-edb8-5d9f-9f37-dd0bb3655e35"}, {"title": "仁孝皇后徐氏安葬于长陵", "description": "永乐十一年二月丙寅，明廷将已故的仁孝皇后徐氏安葬在长陵。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c514c72e-a3ec-5c71-88b7-4725b4e10263"}, {"title": "明成祖到凤阳拜谒皇陵", "description": "永乐十一年二月辛未，明成祖朱棣到达凤阳，拜谒皇陵。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年二月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "950e02b2-75c6-50e8-a2a2-6d0f4a6f049b"}, {"title": "明成祖到达北京", "description": "永乐十一年四月己酉，自京师北行的明成祖朱棣到达北京。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "03e02bda-5069-596f-abf0-a8f65fc92806"}, {"title": "曹县进献称作驺虞的动物，明成祖拒绝庆贺", "description": "永乐十一年五月丁未，曹县进献一种本纪称为驺虞的动物。朝廷的礼官请求举行庆贺，明成祖没有准许。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年五月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33d8d5be-9711-5bc9-a35f-1b55b75616c4"}, {"title": "明廷册封阿鲁台为和宁王", "description": "永乐十一年七月戊寅，明廷册封阿鲁台为和宁王。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年七月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7d12942d-9ce4-5a00-a175-66afd4007e23"}, {"title": "北京发生地震", "description": "永乐十一年八月甲子，北京发生地震。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e3b1c565-8104-5141-b7be-e28aaf725d7e"}, {"title": "顾成出兵征讨思州和靖州", "description": "永乐十一年八月乙丑，镇远侯顾成出兵征讨思州、靖州两地反抗朝廷的苗民。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年八月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "18c65ba1-689e-51c8-b33c-ad9eb2a84b69"}, {"title": "明廷要求地方官每年春天巡视并防治蝗灾", "description": "永乐十一年九月壬午，朝廷下诏要求地方官每年春季巡视辖境。如有蝗虫危害庄稼，应立即捕除。未按诏令办事的，连两司也要一并追究。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年九月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cfe007c1-301a-5b7b-a975-f632cfabe093"}, {"title": "明成祖发诏命皇太子审录囚犯", "description": "永乐十一年十月丙寅，明成祖以加盖御玺的文书，命皇太子朱高炽审录囚犯。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "170d477b-b202-57ae-8550-4e69ef0516c3"}, {"title": "皇太子奉命将野蚕丝被褥献于太庙", "description": "永乐十一年十一月戊寅，朝廷用野蚕茧制成被褥，命皇太子朱高炽将其献到太庙。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十一月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ef24afc-cd89-5363-b186-d5a40b0ff669"}, {"title": "马哈木的部队渡过饮马河，明廷命边将戒备", "description": "永乐十一年十一月壬午，瓦剌首领马哈木的军队渡过饮马河。阿鲁台向明廷告警，明廷命边将加强守备。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十一月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b48215d6-2611-5dc5-a405-21db9ef91c38"}, {"title": "陈懋等巡视宁夏、大同和山西边境", "description": "永乐十一年十一月甲申，宁阳侯陈懋和都督谭青、马聚、朱崇巡查宁夏、大同和山西边境，并拣选操练士卒与战马。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十一月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1e242db4-d9fb-5a0d-9e89-6b6b49a1ffb9"}, {"title": "明廷调兵分别驻守宣府和会集北京", "description": "永乐十一年十一月，在派将巡边后，明廷命陕西、山西和潼关等五卫的兵力驻守宣府，又调中都、辽东、河南三都司和武平等四卫兵力会集北京。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "822d17ff-3e8b-53c7-982f-89281234e592"}, {"title": "孙岩奉命驻防开平", "description": "永乐十一年十一月乙巳，明廷派应城伯孙岩在开平布防。", "start_year": 1413, "end_year": 1413, "time_original": "永乐十一年十一月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "74682b8a-e96b-5405-87b6-50aee83b1316"}, {"title": "张辅、沐晟在爱子江击败交阯对手", "description": "永乐十一年十二月壬子，张辅、沐晟在爱子江重创交阯一带与明军交战的部队。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十一年十二月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9e4fd036-15e3-5ceb-a97c-167d545541bc"}, {"title": "本纪汇记永乐十一年多地入贡", "description": "永乐十一年，别失八里、满剌加、占城和爪哇西王入贡，琉球中山四次入贡，山南两次入贡。各次来使均列在年末汇记。 按原历纪年，事情发生在公元1413至1414年之间。", "start_year": null, "end_year": null, "time_original": "永乐十一年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "850972d9-b042-55df-8c64-428d0b3bf69f"}, {"title": "明廷册封琉球山南王", "description": "朝廷册封本纪所作汪应祖为琉球国山南王。卷末校记指出，本书《琉球传》写作王应祖。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "51dad3e4-4381-5115-b051-f84a12a94521"}, {"title": "郑和再次出使西洋", "description": "永乐十年十一月丙申，《明史》本纪记郑和再度出使西洋。卷末校勘记说明，此日旧作丙辰，因该月没有丙辰日，校为丙申。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年十一月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3f02bd10-5080-5f33-86d8-da4490a24f58"}, {"title": "马哈木攻杀本雅失里", "description": "《明史》瓦剌传将马哈木攻杀本雅失里系于永乐十年。依本纪卷末所引《太宗实录》，五月乙酉，瓦剌来使已经报告本雅失里被杀。卷末校记据此指出，本纪误把此事列在永乐十一年。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年（五月乙酉以前已发生）", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73385e5b-bda8-54bf-adcf-1ac90dda20ad"}, {"title": "本雅失里死后答里巴被立为可汗", "description": "《明史》本纪记载，马哈木攻杀本雅失里之后，立答里巴为可汗。卷末校记校正了本雅失里之死的所属年条，答里巴继立的年月有待核实。", "start_year": null, "end_year": null, "time_original": "本雅失里遇害之后，具体年月待考", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1218afd5-1fe9-5753-8ad7-01b10d7b4ded"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

