INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "永乐十一年正月初一发生日食，朝廷随即下诏取消朝贺和宴会。", "citation": "《明史》卷6·本纪第六·成祖二·mingshi-2f603db3d81e-p001115；永乐十一年正月辛巳朔", "note": "原文：十一年春正月辛巳朔，日有食之，詔罷朝賀宴會；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "d06a2ca7-3611-555d-a6bb-4dbfc80ffe05", "subject_id": "64bcb900-acd0-57c8-b942-abd03f80d78d", "source_id": "3a3a3b78-eda9-52f0-bd03-e6a037d43b5d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历永乐十一年正月辛巳朔。DDBC历表换算所据为1413-02-10至1413-02-10，据此核对公元发生年份。", "citation": "《明史》卷6·本纪第六·成祖二·mingshi-2f603db3d81e-p001115；永乐十一年正月辛巳朔", "note": "原文：十一年春正月辛巳朔，日有食之，詔罷朝賀宴會；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "eb31d9b2-0780-50cb-ab07-691358ba3c1f", "subject_id": "64bcb900-acd0-57c8-b942-abd03f80d78d", "source_id": "3a3a3b78-eda9-52f0-bd03-e6a037d43b5d"}, {"subject_table": "event", "field_path": "description", "claim_text": "永乐十一年正月壬午，明廷告谕通政使和礼科给事中，朝觐官员若隐瞒辖区灾情，待别人上报后发现，要追究该官员的责任。", "citation": "《明史》卷6·本纪第六·成祖二·mingshi-2f603db3d81e-p001115；永乐十一年正月壬午", "note": "原文：壬午，諭通政使、禮科給事中，凡朝覲官境內災傷不以聞為他人所奏者，罪之；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "a076a7a4-0533-5a3f-a948-7dbea0b7417b", "subject_id": "3676ca8b-a664-5cf7-87a0-1fe198725ed5", "source_id": "3a3a3b78-eda9-52f0-bd03-e6a037d43b5d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历永乐十一年正月壬午。DDBC历表换算所据为1413-02-11至1413-02-11，据此核对公元发生年份。", "citation": "《明史》卷6·本纪第六·成祖二·mingshi-2f603db3d81e-p001115；永乐十一年正月壬午", "note": "原文：壬午，諭通政使、禮科給事中，凡朝覲官境內災傷不以聞為他人所奏者，罪之；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "a1719ce0-9c2a-549e-bdea-f4e3c619bf49", "subject_id": "3676ca8b-a664-5cf7-87a0-1fe198725ed5", "source_id": "3a3a3b78-eda9-52f0-bd03-e6a037d43b5d"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱